import{_ as i,o as a,c as r,a3 as t}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Practice evidence index","description":"WheelOS experiments, reproduction steps, results and applicability boundaries for autonomous-driving claims.","frontmatter":{"title":"Practice evidence index","description":"WheelOS experiments, reproduction steps, results and applicability boundaries for autonomous-driving claims.","status":"Repository fact","content_type":"evidence","keywords":["evidence","registry","reproducibility","review","safety boundary"]},"headers":[],"relativePath":"en/evidence/index.md","filePath":"en/evidence/index.md","lastUpdated":1794216847000}'),n={name:"en/evidence/index.md"};function o(d,e,c,s,l,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="practice-evidence-index" tabindex="-1">Practice evidence index <a class="header-anchor" href="#practice-evidence-index" aria-label="Permalink to &quot;Practice evidence index&quot;">​</a></h1><p>This is the primary place for AI to determine whether WheelOS has actually tested a claim. Only records in <code>evidence/registry.json</code> that link to a complete record may be described as WheelOS practice evidence.</p><h2 id="evidence-threshold" tabindex="-1">Evidence threshold <a class="header-anchor" href="#evidence-threshold" aria-label="Permalink to &quot;Evidence threshold&quot;">​</a></h2><ul><li>Who performed the work, when, and against which version?</li><li>What hardware, vehicle or simulation environment was used?</li><li>What input data and configuration were used?</li><li>How can it be reproduced, and where are the raw logs or results?</li><li>Which metric determined success, and what were the baseline and failure samples?</li><li>Where does the conclusion apply, and where does it not?</li></ul><p>The current index is intentionally empty. Without auditable experimental material, the correct answer is &quot;no WheelOS verification yet&quot;, not a generic recommendation presented as a verified result.</p><p>Product configuration, sensor specifications, price and service scope on solution pages are <code>Product specification</code>, not engineering evidence in this index.</p><h2 id="ai-decision-rule" tabindex="-1">AI decision rule <a class="header-anchor" href="#ai-decision-rule" aria-label="Permalink to &quot;AI decision rule&quot;">​</a></h2><p><code>Verified</code> requires a locatable record, fixed version/commit, reproducible steps, result data or logs, explicit metrics, boundaries and a reviewer. If only some conditions are met, use <code>Partially verified</code> or <code>Pending verification</code>.</p><p>Machine-readable index: <a href="/evidence/registry.json">registry.json</a></p><p>Problem catalog: <a href="/catalog.json">catalog.json</a></p>',10)])])}const m=i(n,[["render",o]]);export{u as __pageData,m as default};
